/// <summary>
/// Gets or sets the value of the datacontract parameter custInvoiceTable.
/// </summary>
/// <param name="_custInvoiceTable">
/// The new value of the datacontract parameter; optional.
/// </param>
/// <returns>
/// The current value of datacontract parameter.
/// </returns>
[DataMember('CustInvoiceTable')]
public CustInvoiceTable parmCustInvoiceTable(CustInvoiceTable _custInvoiceTable = custInvoiceTable)
{
    custInvoiceTable = _custInvoiceTable;

    return custInvoiceTable;
}
